Object.assign(quranData,{"85":{"name":"البروج","verses":[{"text":"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ","tafsir":""},{"text":"وَٱلْيَوْمِ ٱلْمَوْعُودِ","tafsir":"أي قسما بالسماء التي هي صاحبة البروج ، جمع برج وهو القطعة من السماء ، سميت برجا لظهوره ، من برج : إذا ظهر ، والبروج هي الحمل والثور والجوزاء والسرطان والأسد والسنبلة والميزان والعقرب والقوس والجدي والدلو والحوت ، والقمر في سيره النفسي يقطع كل برج في ظرف يومين ونصف ، والشمس تقطعه في ظرف شهر."},{"text":"وَشَاهِدٍ وَمَشْهُودٍ","tafsir":"قسما ب ( الْيَوْمِ الْمَوْعُودِ ) وهو يوم القيامة ، الذي وعد به الخلق."},{"text":"قُتِلَ أَصْحَـٰبُ ٱلْأُخْدُودِ","tafsir":"قسما ب ( شاهِدٍ وَمَشْهُودٍ ) في ذلك اليوم ، أو كل شاهد ومشهود. وهذا الأقرب بالعموم ، وإن أورد في التفسير معاني مختلفة لهما."},{"text":"ٱلنَّارِ ذَاتِ ٱلْوَقُودِ","tafsir":"هو الشق العظيم في الأرض ، أي قتل الله أصحاب الأخدود الكفار الذين حفروا الأخاديد في الأرض لتعذيب المؤمنين ، وهذا دعاء على أولئك الكفار ، وكان من قصتهم على ما نقله القمي : إن الذي هيج الحبشة على غزو اليمن ذو نواس ، وهو آخر من ملك من حمير تهود واجتمعت معه حمير على اليهودية ، وسمى نفسه يوسف ، وأقام على ذلك حينا من الدهر ، ثم أخبر أن بنجران بقايا قوم على دين النصرانية وكانوا على دين عيسى وعلى حكم الإنجيل ، ورأس ذلك الدين عبد الله بن برياس ، فحمله أهل دينه على أن يسير إليهم ويحملهم على اليهودية ويدخلهم فيها فسار حتى قدم نجران ، فجمع من كان بها على دين النصرانية ، ثم عرض عليهم دين اليهودية والدخول فيه فأبوا عليه ، فجادلهم وعرض عليهم وحرص الحرص كله النَّارِ ذاتِ الْوَقُودِ (5) إِذْ هُمْ عَلَيْها قُعُودٌ (6) وَهُمْ عَلى ما يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ (7) وَما نَقَمُوا مِنْهُمْ إِلاَّ أَنْ يُؤْمِنُوا بِاللهِ الْعَزِيزِ الْحَمِيدِ (8) فأبوا عليه وامتنعوا من اليهودية والدخول فيها واختاروا القتل ، فاتخذ لهم أخدودا وجمع فيه من الحطب وأشعل فيه النار ، فمنهم من أحرق بالنار ومنهم من قتل بالسيف ومثلّ بهم كل مثلة فبلغ عدد من قتل وأحرق بالنار عشرين ألفا وأفلت رجل منهم يدعى « دوس » (1) ."},{"text":"إِذْ هُمْ عَلَيْهَا قُعُودٌ","tafsir":"بدل عن أخدود أي أصحاب النار ( ذاتِ الْوَقُودِ ) الكثير ، إشارة إلى عظم تلك النار ، والوقود : هو الحطب الذي توقد به النار."},{"text":"وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ","tafsir":"أي أولئك الأصحاب الكفار ( عَلَيْها ) أي على حوالي النار ( قُعُودٌ ) جمع قاعد ، أي كان الكفار قاعدين أطراف النار يشاهدون ما يفعل بالمؤمنين من رميهم فيها."},{"text":"وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ","tafsir":"الملك الكافر وأصحابه ( عَلى ما يَفْعَلُونَ ) جلاوزتهم ( بِالْمُؤْمِنِينَ ) من إلقائهم في النار ( شُهُودٌ ) جمع شاهد ، أي حاضرون مشاهدون ، وهذا ذم لهم كيف رضوا وسمحت لهم أنفسهم بأن يشاهدوا هذا النحو من التعذيب البشع."},{"text":"ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ","tafsir":"أي ما كره الملك وأصحابه من المؤمنين ( إِلَّا أَنْ يُؤْمِنُوا بِاللهِ ) ويتركوا دين الملك الباطل ( الْعَزِيزِ ) الغالب في سلطانه ( الْحَمِيدِ ) المجرد في أفعاله ، إشارة إلى أن الغلب كان للمؤمنين ، ( 1) تفسير القمي : ج 2 ص 413. الَّذِي لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَاللهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ (9) إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِناتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذابُ جَهَنَّمَ وَلَهُمْ عَذابُ الْحَرِيقِ (10) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ذلِكَ الْفَوْزُ الْكَبِيرُ (11) وإن صال الملك وجال أياما ، كما أن ما فعل بالمؤمنين كان لحكمة وصلاح لهم لعلو درجاتهم."},{"text":"إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ","tafsir":"فهو المالك المطلق لهما ( وَاللهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ ) أي حاضر عالم ، فلم يغب عنه ما فعلوا بالمؤمنين فسينتقم منهم."},{"text":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ","tafsir":"أي عذبوهم وأحرقوهم بنار الأخدود ، من أصحاب ذلك الملك الطاغي ( ثُمَّ لَمْ يَتُوبُوا ) بعد ذلك بالإيمان والطاعة ( فَلَهُمْ عَذابُ جَهَنَّمَ ) في الآخرة بكفرهم ( وَلَهُمْ عَذابُ الْحَرِيقِ ) بما أحرقوا المؤمنين ، وكأن المراد بعذاب جهنم سائر أنواع عذابها من لدغ السامات وأكل الزقوم ، وشرب الغسلين وما أشبه ، و « حريق » اسم النار ، ولذا أضيف إليه « عذاب » . [12] وفي مقابل أولئك المؤمنون ( إِنَّ الَّذِينَ آمَنُوا ) بالله ورسوله واليوم الآخر ( وَعَمِلُوا ) الأعمال ( الصَّالِحاتِ لَهُمْ جَنَّاتٌ ) أي بساتين ، وسميت جنة لتستر أرضها بالأشجار والقصور ( تَجْرِي مِنْ تَحْتِهَا ) أي من تحت قصورها وأشجارها ( الْأَنْهارُ ) من عسل ولبن وخمر وماء وغيرها ( ذلِكَ ) التنعم بتلك الجنات ( الْفَوْزُ ) والفلاح ( الْكَبِيرُ ) الذي ليس فوقه فوز. ولعل المراد ب ( إِنَّ الَّذِينَ فَتَنُوا ) ، و ( إِنَّ الَّذِينَ إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ (12) إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ (13) وَهُوَ الْغَفُورُ الْوَدُودُ (14) ذُو الْعَرْشِ الْمَجِيدُ (15) فَعَّالٌ لِما يُرِيدُ (16) هَلْ أَتاكَ حَدِيثُ الْجُنُودِ (17) آمَنُوا ) ، مطلق الكفار والمؤمنين ، لا خصوص الكافر والمؤمن من أصحاب الأخدود ، أو أصحاب الرسول ومعاصريه."},{"text":"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ","tafsir":""},{"text":"إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ","tafsir":"يا رسول الله ، أي أخذه للكافرين وانتقامه منهم ( لَشَدِيدٌ ) فانه إذا بطش بأحد يغشاه العذاب ، بمختلف ألوانه وصنوفه ، فليحذر الكفار والعصاة بطشه."},{"text":"وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ","tafsir":"سبحانه ( هُوَ يُبْدِئُ ) الخلق ، بأن يعطيهم الحياة من العدم أولا ( وَيُعِيدُ ) للخلق بعد الممات أحياء."},{"text":"ذُو ٱلْعَرْشِ ٱلْمَجِيدُ","tafsir":"لمن تاب وآمن ، أي كثير المغفرة ( الْوَدُودُ ) الذي يحب الناس فلا يريد تعذيبهم إلا إذا تمادوا في الكفر والعصيان."},{"text":"فَعَّالٌ لِّمَا يُرِيدُ","tafsir":"وهو كناية عن أن له الملك ، يقال للملك « صاحب العرش » كناية عن سلطانه ، وإن لم يكن له كرسي يجلس عليه ( الْمَجِيدُ ) الموصوف بالمجد والعظمة."},{"text":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ","tafsir":"أي كثير الفعل ( لِما يُرِيدُ ) فكل شيء أراده فعله لا يمتنع عليه شيء ، وهذه الآيات للإلماع إلى وجوب رجاء البشر إياه ، وخوفهم منه ، لأن له الملك والعظمة وأنه يفعل ما يشاء فعله. [18] ثم جاء السياق لبيان شاهد على ما تقدم من أنه سبحانه يفعل ما يريد ، ليرجوه المؤمن ويخافه الكافر ( هَلْ أَتاكَ ) يا رسول الله أو أيها السامع ( حَدِيثُ الْجُنُودِ ) أي هل بلغك خبر الذين تجندوا على خلاف الله فِرْعَوْنَ وَثَمُودَ (18) بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ (19) وَاللهُ مِنْ وَرائِهِمْ مُحِيطٌ (20) بَلْ هُوَ قُرْآنٌ مَجِيدٌ (21) فِي ل َوْحٍ مَحْفُوظٍ (22) ومحاربة أنبيائه ، لتعرف كيف صنع الله بهم ؟"},{"text":"فِرْعَوْنَ وَثَمُودَ","tafsir":""},{"text":"بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ","tafsir":"وجنده ، الذين أرسل إليهم موسى عليه‌السلام ( وَثَمُودَ ) الذين أرسل إليهم صالح عليه‌السلام ، فإنهم لما كذبوا الأنبياء عذبهم الله سبحانه ، وهكذا عادة الله سبحانه مع المكذبين. [20] إن كفار مكة لا يرعوون عن كفرهم وعصيانهم بهذه الأمثال والقصص ( بَلِ الَّذِينَ كَفَرُوا ) بالله ورسوله ( فِي تَكْذِيبٍ ) للإسلام والقرآن ، أي مشغولون عنه ، ومعرضون عن الحق."},{"text":"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ","tafsir":""},{"text":"بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ","tafsir":"أي من جوانبهم ( مُحِيطٌ ) كأنهم في دائرة علم الله سبحانه الشامل ، وقدرته الواسعة فيعلم ماذا يصنعون ، وهم في قبضة قدرته ، يقول الملك « أنا محيط بفلان » يريد إحاطة علمه وقدرته لا إحاطة الجسم. [22] وليس كما ذكر الكفار إن القرآن شعر أو كهانة أو ما أشبه ( بَلْ هُوَ قُرْآنٌ مَجِيدٌ ) ، ذو مجد وعظمة لأنه من قبله سبحانه."},{"text":"فِى لَوْحٍ مَّحْفُوظٍۭ","tafsir":""}]},"86":{"name":"الطارق","verses":[{"text":"وَٱلسَّمَآءِ وَٱلطَّارِقِ","tafsir":""},{"text":"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ","tafsir":"أي قسما بالسماء ( وَالطَّارِقِ ) أي قسما بالطارق وهو الذي يأتي ليلا ، سمي طارقا لأنه يطرق الباب ، أما في النهار فقد كانت العادة الجارية لديهم أن تفتح الأبواب ، فإذا جاء أحد استأذن ودخل ، والمراد به هنا النجم الذي يطلع ليلا."},{"text":"ٱلنَّجْمُ ٱلثَّاقِبُ","tafsir":"أيها الإنسان ، أو أيها الرسول ( ما ) هو ( الطَّارِقُ ) ؟ وذلك لتعظيم شأنه. [4] هو ( النَّجْمُ الثَّاقِبُ ) الذي يثقب السماوات بنوره ، ومن يعرف عظم النجوم وكثرة بعدها حتى أنها تحتاج إلى سنوات ضوئية حتى توصل نورها إلى الأرض يعرف عظم هذا القسم. والظاهر أن المراد بالنجم الجنس لا خصوص نجم واحد ، وما ذكر له في التفسير من المصداق فهو من باب المثال."},{"text":"إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ","tafsir":""},{"text":"فَلْيَنظُرِ ٱلْإِنسَـٰنُ مِمَّ خُلِقَ","tafsir":"أي ما كل إنسان ( لَمَّا عَلَيْها حافِظٌ ) أي إلّا عليها حافظ من قبل الله سبحانه ، وهم الملائكة الذين يحفظون البشر من المهالك كما يحفظون أعمالهم ، وهذا هو متعلق القسم. [6] وإذا كان الإنسان في شكّ من الإله فليفكر في أصله ونشأته ( فَلْيَنْظُرِ الْإِنْسانُ ) أي ليفكر ويتدبر ( مِمَّ خُلِقَ ) أي مما ذا خلق ؟ وما هو أصله ؟"},{"text":"خُلِقَ مِن مَّآءٍ دَافِقٍ","tafsir":""},{"text":"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ","tafsir":"أي ماء يدفق ، والدفق هو الصب الذي فيه دفع وقوة ، فإن المني يخرج هكذا. يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرائِبِ (7) إِنَّهُ عَلى رَجْعِهِ لَقادِرٌ (8) يَوْمَ تُبْلَى السَّرائِرُ (9) فَما لَهُ مِنْ قُوَّةٍ وَلا ناصِرٍ (10) وَالسَّماءِ ذاتِ الرَّجْعِ (11) وَالْأَرْضِ ذاتِ الصَّدْعِ (12)"},{"text":"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ","tafsir":"ذلك الماء الذي هو مبدأ الإنسان ( مِنْ بَيْنِ الصُّلْبِ ) للرجل ، وهو العظم الذي في ظهره مركز المني ( وَالتَّرائِبِ ) نواحي الصدر ، واحدتها تريبة ، فإن مني المرأة مركزه هناك. [9] إن الله خلق الإنسان بهذه الكيفية ( إِنَّهُ عَلى رَجْعِهِ ) أي إرجاعه إلى الحياة بعد الموت ( لَقادِرٌ ) كما قدر على ابتداء خلقه حين لم يكن شيئا مذكورا. [10] قادر على رجعه في ( يَوْمَ تُبْلَى السَّرائِرُ ) أي تختبر الضمائر ، فإن « سرائر » جمع سريره ، وهي المحل الكامن في الإنسان ، فإن يوم القيامة تظهر بواطن الناس وما انطووا عليه من خير وشر."},{"text":"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ","tafsir":""},{"text":"فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ","tafsir":""},{"text":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ","tafsir":"أي للإنسان ( مِنْ قُوَّةٍ ) يدفع بها العذاب ( وَلا ناصِرٍ ) ينصره من تلك الأهوال ، فليخش وليحذر أن يخالف الله سبحانه حتى لا يبتلي بالعذاب."},{"text":"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ","tafsir":"أي قسما بالسماء ( ذاتِ الرَّجْعِ ) ، التي ترجع في كل دورة إلى مكانها الأول ، أو ذات المطر ، وسمي المطر رجعا لأنه يرجع كل نفسه ، أو لأنه يرجع إلى الأرض بعد التصاعد منها بالأبخرة."},{"text":"إِنَّهُۥ لَقَوْلٌ فَصْلٌ","tafsir":"أي قسما بالأرض ( ذاتِ الصَّدْعِ ) التي تتصدع وتتشقق فيخرج منها النبات. إِنَّهُ لَقَوْلٌ فَصْلٌ (13) وَما هُوَ بِالْهَزْلِ (14) إِنَّهُمْ يَكِيدُونَ كَيْداً (15) وَأَكِيدُ كَيْداً (16) فَمَهِّلِ الْكافِرِ ينَ أَمْهِلْهُمْ رُوَيْداً (17)"},{"text":"وَمَا هُوَ بِٱلْهَزْلِ","tafsir":"أي القرآن ، أو ما ذكره من رجوع الخلق بعد الموت وتشقق الأرض عنهم ، وهذا هو المناسب للآيتين السابقتين ( لَقَوْلٌ فَصْلٌ ) يفصل بين الحق والباطل."},{"text":"إِنَّهُمْ يَكِيدُونَ كَيْدًا","tafsir":"أي اللعب ، فإنه كلام واقعي لا أنه قيل على وجه اللعب والهزل."},{"text":"وَأَكِيدُ كَيْدًا","tafsir":"أي الكفار ( يَكِيدُونَ ) ويحتالون لإبطال هذا الكلام الذي هو قول فصل ( كَيْداً ) بقولهم إنه شعر وسحر وكهانة وما أشبه ذلك."},{"text":"فَمَهِّلِ ٱلْكَـٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا","tafsir":"أي أريد أمرا آخر ضد ما يريدون ، وسمي كيدا للمشابهة ( كَيْداً ) كما أنهم يكيدون."}]},"87":{"name":"الأعلى","verses":[{"text":"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى","tafsir":""},{"text":"ٱلَّذِى خَلَقَ فَسَوَّىٰ","tafsir":"أي نزّه يا رسول الله ، أو أيها المخاطب ( اسْمَ رَبِّكَ ) عما لا يليق به من الشرك والولد ، فلا تنسب إليه شيئا ينافي مقام الألوهية وذكر « اسم » للتعظيم ، فمن يجب أن يسبح اسمه يجب أن يسبح هو بالأولى ( الْأَعْلَى ) أي الأرفع من كل شيء ، فلا شيء أرفع منه في العلم أو القدرة أو الخلق أو الرزق أو غير ذلك من سائر صفات الذات وصفات الفعل."},{"text":"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","tafsir":"الخلق كلهم ( فَسَوَّى ) بينهم في الإحكام والإتقان والدقة ، فليس بعض الخلق متقنا وبعضه غير متقن ، كما سوّى خلق كل شيء فأعطاه ما يصل به إلى الكمال اللائق به من الأجهزة والآلات."},{"text":"وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ","tafsir":"والتقدير هو التخطيط ، كما يقدر المهندس البناء ثم يبنيه ( فَهَدى ) كل ذي روح إلى مصالحه ، فهو خلق ، وإعطاء أجهزة ، وتقدير للحياة ، وهداية."},{"text":"فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ","tafsir":"أي أنبت الحشيش الذي ترعاه الحيوانات من الأرض."},{"text":"سَنُقْرِئُكَ فَلَا تَنسَىٰٓ","tafsir":"أي المرعى بعد الخضرة ( غُثاءً ) أي هشيما جافا كالغثاء الذي تراه فوق السيل ، بمعنى المجتمع من هنا وهناك بلا علاقة وارتباط ومشابهة ( أَحْوى ) أي أسود بعد الخضرة ، فإن الحوة بمعنى السواد. سَنُقْرِئُكَ فَلا تَنْسى (6) إِلاَّ ما شاءَ اللهُ إِنَّهُ يَعْلَمُ الْجَهْرَ وَما يَخْفى (7) وَنُيَسّ ِرُكَ لِلْيُسْرى (8) [7] ومن هدايته سبحانه أنه أنزل القرآن على الرسول ، و قد قال ابن عباس : كان النبي صلى‌الله‌عليه‌وآله‌وسلم إذا أنزل عليه جبرئيل بالوحي يقرأه مخافة أن ينساه ، فكان لا يفرغ جبرئيل من آخر الوحي حتى يشرع الرسول في القراءة. فأنزل الله تعالى عليه هذه الآية (1) ( سَنُقْرِئُكَ ) القرآن ، أي نتلو عليك لتقرأه ( فَلا تَنْسى ) منه شيئا ، فقد شاءت إرادته سبحانه أن يكون النبي صلى‌الله‌عليه‌وآله‌وسلم منزّها عن النسيان ، وكذلك سائر الأنبياء عليهم‌السلام . أما قوله « تنسى » فهو من قبيل ( إِنَّا نَسِيناكُمْ ) (2) ، ولعل العمل كان تعليما للمسلمين فيما بعد بأن يحرصوا على القرآن مثل هذا الحرص."},{"text":"إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","tafsir":""},{"text":"وَنُيَسِّرُكَ لِلْيُسْرَىٰ","tafsir":"أن تنساه ، وفيه دلالة على أن عدم نسيانه إنما هو من الله سبحانه ، حتى أنه إذا شاء غيره قدر عليه ، قالوا : ودخول المشيئة في هذه الآية للدلالة على أن النبي مهما بلغ من العظمة فإن جميع أموره بيده تعالى ( إِنَّهُ ) سبحانه ( يَعْلَمُ الْجَهْرَ ) من الكلام ( وَما يَخْفى ) كالسر والنجوى ، فكل ذلك من الإقراء وعدم النسيان إلا بمشيئته تابع لعلمه الواسع الذي يشمل كل شيء ، وبما علّمه من الصلاح جعل النبي صلى‌الله‌عليه‌وآله‌وسلم بحيث لا ينسى ، وإلا فلو كان ينسى لم يؤمن على التبليغ ، لتطرق احتمال النسيان في كل شيء من أقواله وأفعاله."},{"text":"فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ","tafsir":"يا رسول الله ، أي نوفقك ( لِلْيُسْرى ) أي الطريقة اليسرى ( 1) مجمع البيان : ج 10 ص 329. ( 2) السجدة : 15. فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرى (9) سَيَذَّكَّرُ مَنْ يَخْشى (10) وَيَتَجَنَّبُهَا الْأَشْقَى (11) الَّذِي يَصْلَى النَّارَ الْكُبْرى (12) ثُمَّ لا يَمُوتُ فِيها وَلا يَحْيى (13) قَدْ أَفْلَحَ مَنْ تَزَكَّى (14) في جميع الأمور ، فإن أحكامه سبحانه توصل إلى السعادة بأيسر الطرق وأسهلها."},{"text":"سَيَذَّكَّرُ مَن يَخْشَىٰ","tafsir":"يا رسول الله الناس بما أودع فيهم من الفطرة الدالة على الألوهية والمعاد وما أشبه ( إِنْ نَفَعَتِ الذِّكْرى ) أي إن كان الذكر في معرض النفع ولو إتمام الحجة ، أما إذا علم الرسول أن ذكره لا ينفع إطلاقا في الهداية لليأس ، ولا في إتمام الحجة لتمام الحجة على المخاطبين سابقا ، فلا لزوم للتذكير. وقيل « إن » بمعنى « قد » أي قد نفعت الذكرى ، بمعنى قد تنفع."},{"text":"وَيَتَجَنَّبُهَا ٱلْأَشْقَى","tafsir":"أصله « يتذكر » أدغمت التاء في الذال وجيء بهمزة الوصل لتعذر الابتداء بالساكن ( مَنْ يَخْشى ) أي سيتعظ بالقرآن وبكلامك من يخشى عقاب الله سبحانه."},{"text":"ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ","tafsir":"أي يبتعد عن الموعظة والذكرى ( الْأَشْقَى ) أي الأكثر شقوة ، فإن الكافر المجتنب للذكرى أكثر شقاء من العاصي."},{"text":"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","tafsir":"أي يدخل ويلازم ( النَّارَ الْكُبْرى ) وهي نار جهنم."},{"text":"قَدْ أَفْلَحَ مَن تَزَكَّىٰ","tafsir":"أي في تلك النار ليستريح ( وَلا يَحْيى ) حياة هادئة مريحة."},{"text":"وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ","tafsir":"أي فاز ونجح ( مَنْ تَزَكَّى ) أي تطهر باجتناب الرذائل ، والتحلي بالفضائل. وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى (15) بَلْ تُؤْثِرُونَ الْحَياةَ الدُّنْيا (16) وَالْآخِرَةُ خَيْرٌ وَأَبْقى (17) إِنَّ هذا لَفِي الصُّحُفِ الْأُولى (18) صُحُفِ إِبْراهِيمَ وَمُوسى (19)"},{"text":"بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","tafsir":"أي تذكر الله سبحانه بقلبه ، والإتيان ب « اسم » للتعظيم ( فَصَلَّى ) لله ، أي خضع وخشع ، أو أتى بالصلاة فإنها دليل خشوع الإنسان وتذكره لله تعالى. وفي بعض الروايات أن المراد بها زكاة الفطرة وصلاة العيد ، والظاهر أنها من باب المصداق ، وانطباق الكلي على مصاديقه يمكن أن يكون بعد مدة ـ عند وجود المصداق فلا يقال : كيف يصح والسورة مكية ولم يكن هناك زكاة فطرة ولا صلاة عيد ؟"},{"text":"وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ","tafsir":"أنتم أيها الناس لا تفعلون ذلك ، وإنما ( تُؤْثِرُونَ ) أي تختارون ( الْحَياةَ الدُّنْيا ) أي الحياة القريبة ، تختارونها على الآخرة فتصرفون أموالكم وأوقاتكم في ملاذّها ، لا في الزكاة والصلاة."},{"text":"إِنَّ هَـٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ","tafsir":"أي الجنة ( خَيْرٌ ) من الدنيا ، لأن نعيمها أكثر ولا يشوبها كدر ( وَأَبْقى ) لأنها دائمة مستمرة ، بخلاف الدنيا فإنها فانية زائلة."},{"text":"صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ","tafsir":"الذي ذكر من فلاح المتزكي المصلي ، أو سائر ما ذكر في هذه السورة ( لَفِي الصُّحُفِ الْأُولى ) فكل كتب الله المنزلة تحرض على الزكاة والصلاة وسائر الخيرات ، وليس هذا بدعا من القرآن."}]},"88":{"name":"الغاشية","verses":[{"text":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَـٰشِيَةِ","tafsir":""},{"text":"وُجُوهٌ يَوْمَئِذٍ خَـٰشِعَةٌ","tafsir":"أيها الإنسان ، أو يا رسول الله ( حَدِيثُ الْغاشِيَةِ ) أي خبر القيامة ؟ وتسمى بالغاشية لأنها تغشى الناس بأهوالها ، والاستفهام للإلفات والإيقاظ."},{"text":"عَامِلَةٌ نَّاصِبَةٌ","tafsir":"أي في يوم القيامة ( خاشِعَةٌ ) ذليلة بسبب ما عملت من الكفر والآثام ، وإنما نسب الخشوع إلى الوجوه لظهوره فيها."},{"text":"تَصْلَىٰ نَارًا حَامِيَةً","tafsir":"قد عملت في النار وكدت ( ناصِبَةٌ ) وتعبت ، فإن النصب بمعنى التعب ، ولكنها لم تنتفع بأعمالها وأتعابها ، بل بالعكس صارت دنياه سببا للعذاب والعقاب."},{"text":"تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ","tafsir":"أي تدخل تلك الوجوه النار وتلازمها ( حامِيَةً ) قد حميت حتى تناهت في الحرّ."},{"text":"لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ","tafsir":"أي أصحاب تلك الوجوه ، وقد أطلق الوجوه على أصحابها بعلاقة الجزء والكل ، من قبيل إطلاق « الرقبة » على الإنسان ( مِنْ عَيْنٍ آنِيَةٍ ) قد بلغت حرارتها وأناها إلى منتهى الدرجة ، فإن آنية بمعنى البالغة أشد درجات الحرارة. [7] ذاك شرابهم ، فما هو طعامهم ؟ ( لَيْسَ لَهُمْ طَعامٌ إِلَّا مِنْ ضَرِيعٍ ) وهو نبت يضر ولا ينفع. و في حديث عن النبي صلى‌الله‌عليه‌وآله‌وسلم إنه شيء يكون في النار يشبه الشوك أمرّ من الصبر وأنتن من الجيفة وأشد حرّا من النار (1) . ( 1) مجمع البيان : ج 10 ص 336. لا يُسْمِنُ وَلا يُغْنِي مِنْ جُوعٍ (7) وُجُوهٌ يَوْمَئِذٍ ناعِمَةٌ (8) لِسَعْيِها راضِيَةٌ (9) فِي جَنَّةٍ عالِيَةٍ (10) لا تَسْمَعُ فِيها لاغِيَةً (11) فِيها عَيْنٌ جارِيَةٌ (12) فِيها سُرُرٌ مَرْفُوعَةٌ ( 13) وَأَكْوابٌ مَوْضُوعَةٌ (14)"},{"text":"لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ","tafsir":""},{"text":"وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ","tafsir":"أكله ( وَلا يُغْنِي مِنْ جُوعٍ ) فآكله يحس بالجوع بعد أكله كما يحس بالجوع قبل أكله. [9] ذلك أحوال العصاة فلننظر إلى أحوال المتقين ( وُجُوهٌ يَوْمَئِذٍ ) أي في يوم القيامة ( ناعِمَةٌ ) منعمة في أنواع اللذات ظاهر عليها أثر النعمة والسرور."},{"text":"لِّسَعْيِهَا رَاضِيَةٌ","tafsir":""},{"text":"فِى جَنَّةٍ عَالِيَةٍ","tafsir":"في الدنيا وما عملت سابقا ( راضِيَةٌ ) حيث قد حصلت على الجنة بسببها."},{"text":"لَّا تَسْمَعُ فِيهَا لَـٰغِيَةً","tafsir":"رفيعة المكان والقدر ، فإن قصورها ومكانها في أعالي الجو."},{"text":"فِيهَا عَيْنٌ جَارِيَةٌ","tafsir":"أولئك الأشخاص أصحاب الوجوه الناعمة ( فِيها ) في الجنة ( لاغِيَةً ) أي كلمة ساقطة لا فائدة فيها."},{"text":"فِيهَا سُرُرٌ مَّرْفُوعَةٌ","tafsir":"أي في تلك الجنة ( عَيْنٌ جارِيَةٌ ) تجري حتى يتناول الماء كل إنسان يمر بها ، والماء الجاري أطيب ذوقا وأجمل في النظر."},{"text":"وَأَكْوَابٌ مَّوْضُوعَةٌ","tafsir":"أي في تلك الجنة ( سُرُرٌ ) جمع سرير ، وهو الكرسي ( مَرْفُوعَةٌ ) في المكان ، وفي القيمة ، وفي القدر."},{"text":"وَنَمَارِقُ مَصْفُوفَةٌ","tafsir":"جمع كوب ، وهو قدح صغير جميل ( مَوْضُوعَةٌ ) على حافات الأنهر للاستقاء والشرب ، وفي تقابل « موضوعة » ل « مرفوعة » وَنَمارِقُ مَصْفُوفَةٌ (15) وَزَرابِيُّ مَبْثُوثَةٌ (16) أَ فَلا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ (17) وَإِلَى السَّماءِ كَيْفَ رُفِعَتْ (18) وَإِلَى الْجِبالِ كَيْفَ نُصِبَتْ (19) بلاغة بديعة."},{"text":"وَزَرَابِىُّ مَبْثُوثَةٌ","tafsir":"جمع نمرقة ، وهي الوسادة التي يتكأ عليها ( مَصْفُوفَةٌ ) قد صف بعضها إلى جانب البعض."},{"text":"أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ","tafsir":"جمع زربي ، وهو البساط ( مَبْثُوثَةٌ ) أي منتشرة مفروشة للجلوس عليها. [18] وإذ ذكر سبحانه بعض أحوال الجنة والنار عطف السياق نحو الأدلة الدالة على الألوهية ، تعبئة للناس نحو السعادة الأبدية ( أَ فَلا يَنْظُرُونَ ) هؤلاء المنكرون للخالق ( إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ ) في إحكام وتدقيق ، وليس لأي حيوان بالذات خصوصية ، في التذكير بالله سبحانه والدلالة عليه ، إذ كل حيوان آية دالة على وجود الله وسائر صفاته ، وإنما ذكر الإبل لأنها إحدى الآيات الأليفة للعرب ، مع مناسبة لها بسائر ما ذكر في الآيات التالية فإن السماء المرفوعة والأرض المسطوحة الوسيعة والجبال المرفوعة إنما تلائمها الإبل السائرة عبر الصحاري حيث لا شيء إلا الأرض والجبال والسماء."},{"text":"وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ","tafsir":""},{"text":"وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ","tafsir":"؟ والمراد بها الكواكب ، أو المدارات ، أو ما يرى من الهواء الملون."},{"text":"وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ","tafsir":"على الأرض كالأوتاد لئلّا تزول وتتحرك وتضطرب ؟. وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ (20) فَذَكِّرْ إِنَّما أَنْتَ مُذَكِّرٌ (21) لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍ (22) إِلاَّ مَنْ تَوَلَّى وَكَفَرَ (23) فَيُعَذِّبُهُ اللهُ الْعَذابَ الْأَكْبَرَ (24) إِنَّ إِلَيْنا إِيابَهُمْ (25) ثُمَّ إِنَّ عَلَيْنا حِسابَهُمْ (26)"},{"text":"فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ","tafsir":"؟ أي بسطت لتصلح طرائق للناس ، والمراد أ فلا يتفكرون في هذه المخلوقات حتى يستدلوا بها على وجوده سبحانه وسائر صفاته ؟ والاستفهام للتوبيخ والتقريع."},{"text":"لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ","tafsir":"يا رسول الله الناس بهذه الآيات ( إِنَّما أَنْتَ مُذَكِّرٌ ) تبين لهم الحقائق ليتذكروا ما أودع في فطرتهم من الألوهية والمعاد وما أشبه."},{"text":"إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","tafsir":"أي على هؤلاء القوم ( بِمُصَيْطِرٍ ) أي بمسلط ، حتى تكون مسئولا عن انحرافهم ، وإنما شأن الأنبياء التذكير والوعظ ، فمن شاء اهتدى ومن شاء انحرف."},{"text":"فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ","tafsir":"، فإن الذكرى تنفع ( إِلَّا ) في ( مَنْ تَوَلَّى ) أي من أعرض عن الحق ( وَكَفَرَ ) بالله واليوم الآخر ، وذلك لا يفلت من قبضة الله سبحانه."},{"text":"إِنَّ إِلَيْنَآ إِيَابَهُمْ","tafsir":"وهو عذاب الآخرة."},{"text":"ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم","tafsir":"أي إلى جزائنا وحسابنا ( إِيابَهُمْ ) أي رجوعهم بعد الموت ، من « آب » بمعنى رجع."}]},"89":{"name":"الفجر","verses":[{"text":"وَٱلْفَجْرِ","tafsir":""},{"text":"وَلَيَالٍ عَشْرٍ","tafsir":"أي قسما بالفجر ، وهو انفجار الصبح قبل طلوع الشمس ، فإن النور يظهر ممتدا في جانب المشرق قبل ساعة ونصف من الطلوع."},{"text":"وَٱلشَّفْعِ وَٱلْوَتْرِ","tafsir":"أي قسما بالليالي العشر من ذي الحجة ـ على ما ذكروا ـ وكأن الحلف هنا بما ينشأ منه الخير ، فإن الفجر ينشأ منه الضياء ، وهذه الليالي محل الأعمال والطاعات."},{"text":"وَٱلَّيْلِ إِذَا يَسْرِ","tafsir":"قسما ب ( الشَّفْعِ ) ركعتا صلاة الليل ( وَالْوَتْرِ ) الركعة الأخيرة منها ، أو الشفع يوم تروية ، والوتر يوم عرفة ـ كما روي ـ ."},{"text":"هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ","tafsir":"قسما ب ( اللَّيْلِ إِذا يَسْرِ ) أي يمضي ، كقوله : ( وَاللَّيْلِ إِذْ أَدْبَرَ ) (1) وأصله « يسري » حذف الياء للسياق ، والمقسم له محذوف ، تقديره لنعاقب الكفار ، دلّ عليه قوله « ألم تر .. » ."},{"text":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","tafsir":"الذي تقدم من الأيمان ( قَسَمٌ ) يكن ( لِذِي حِجْرٍ ) أي ذي عقل ؟ فإن « الحجر » من أسماء العقل ، سمي بذلك لأنه يحجر صاحبه عن الإتيان بما لا يليق به ، والاستفهام للتأنيب ، بمعنى كيف لا تصدقون بما نقول بعد هذه الأيمان ؟."},{"text":"إِرَمَ ذَاتِ ٱلْعِمَادِ","tafsir":"يا رسول الله ، أو أيها السامع ، والمراد بالرؤية العلم ، أي ألم تعلم ( كَيْفَ فَعَلَ رَبُّكَ بِعادٍ ) أي بقبيلة عاد ؟"},{"text":"ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَـٰدِ","tafsir":"عطف بيان ل « عاد » ، وهي اسم أرض بنت عاد عليها أبنية فخمة ( 1) المدثر : 34. ذاتِ الْعِمادِ (7) الَّتِي لَمْ يُخْلَقْ مِثْلُها فِي الْبِلادِ (8) وَثَمُودَ الَّذِينَ جابُوا الصَّخْرَ بِالْوادِ (9) وَفِرْعَوْنَ ذِي ا لْأَوْتادِ (10) جميلة ، وإنما مع أن تكون « إرم » عطف بيان ، لأن « عادا » اسم لقبيلتين « عاد » الأولى و « عاد » الثانية ، فالأولى كانت صاحبة « إرم » والتقدير « عاد إرم » ، وهذا كما تقول « مررت ببني هاشم ، المدينة المنورة » ( ذاتِ الْعِمادِ ) جمعه عمد ، أي أبنية إرم التي كانت لها أعمدة ، ويستعمل العماد في القوة والشرف ، يقال « فلان رفيع العماد » . فقد قالوا إن « شداد » من أبناء « عاد » توسع سلطانه ، وعظم أمره ، وكان كافرا بالله ، فسمع بالجنة وأوصافها ، فقال نبني في الأرض مثلها ، فبناها في « إرم » وسميت بهذا الاسم ، وكانت عظيمة فخمة جميلة ذات قصور وحدائق وأثاث ورياش ، فلما أن أراد هو وقومه وجيشه دخولها أهلكهم الله سبحانه ، بأن بعث عليهم صيحة عظيمة فهلكوا جميعا."},{"text":"وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ","tafsir":"أي مثل قبيلة عاد ـ في القوة والثروة وما أشبه ـ أو مثل « إرم » في الفخامة والضخامة والجمال ( فِي الْبِلادِ ) والظاهر أن المراد عدم خلق مثلها في تلك الأزمنة ، لا مطلقا."},{"text":"وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ","tafsir":"ألم تر كيف فعل ربك ب ( ثَمُودَ ) قوم صالح ( الَّذِينَ جابُوا الصَّخْرَ ) أي قطعوا الصخور من الجبال ، وجاؤوا بها ( بِالْوادِ ) أي وادي قرى ، وهو مسكنهم فبنوا بها البيوت الصخرية ؟"},{"text":"ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَـٰدِ","tafsir":"ألم تر كيف فعل ربك ب ( فِرْعَوْنَ ذِي الْأَوْتادِ ) جمع « وتد » الذي كان يدق في جسم مخالفيه الوتد ، ويذره حتى يموت ـ كما قيل ـ الَّذِينَ طَغَوْا فِي الْبِلادِ (11) فَأَكْثَرُوا فِيهَا الْفَسادَ (12) فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذابٍ (13) إِنَّ رَبَّكَ لَبِالْمِرْصادِ (14) فَأَمَّا الْإِنْ سانُ إِذا مَا ابْتَلاهُ رَبُّهُ والمراد به فرعون موسى عليه‌السلام وقد مثل الله سبحانه بأقوى الأمم في زمانهم ، ليبين أنهم حيث عتوا وخالفوا أوامر الله سبحانه أهلكهم سبحانه ولم تنفعهم قوتهم شيئا ومصير هؤلاء الكفار ـ الذين هم أضعف من أولئك ـ مصير أولئك لو تمادوا في الكفر والطغيان."},{"text":"فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ","tafsir":"أي تجبروا على أنبياء الله ، وعملوا بالكفر والمعاصي."},{"text":"فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ","tafsir":"أي في البلاد ( الْفَسادَ ) بالقتل والفجور وغيرهما."},{"text":"إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ","tafsir":"وإنما عبر عن العذاب بالسوط لشدة إيلامه ، ونسب إليه الصب لأن السوط حيث فيه لين يأتي إلى الجسم تدريجيا مشابها للصب ، الذي يأتي على الجسم بتدريج ـ وفي هذا التعبير من البلاغة ما لا يخفى ـ ."},{"text":"فَأَمَّا ٱلْإِنسَـٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ","tafsir":"يا رسول الله ( لَبِالْمِرْصادِ ) هو المحل الذي يجلس الإنسان ليرصد ويراقب أحوال غيره ـ من حيث لا يرونه ـ وهذا كناية عن أنه سبحانه مطلع على الناس ، فمن كفر وأساء مراقب من قبله تعالى ، لا يفوته. [16] وهكذا يطغي الإنسان ـ ليكون له ذلك المصير ـ إذا لم يسترشد بإرشادات الله تعالى ( فَأَمَّا الْإِنْسانُ ) والمراد به الذي لم يهتد بنور الإيمان ( إِذا مَا ابْتَلاهُ رَبُّهُ ) أي امتحنه واختبره ، و « ما » مزيدة جيئت فَأَكْرَمَهُ وَنَعَّمَهُ ف َيَقُولُ رَبِّي أَكْرَمَنِ (15) وَأَمَّا إِذا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهانَنِ (16) كَلاَّ بَلْ لا تُكْرِمُونَ للتأكيد ، ولعل النكتة في زيادتها الإلماع إلى أن « ابتلاءه » ليس بابتلاء حقيقة ، وإنما هو شيء طفيف يصيبه ومع ذلك لا ينجح في الامتحان ( فَأَكْرَمَهُ وَنَعَّمَهُ ) بأن جعل له مكانا كريما ذا شرافة ، ونعمة وافرة ، ليختبره هل يعمل بوظيفته في الثروة والجاه أم لا ؟ فيفرح بذلك ويظنه ثوابا له وجزاء على عمله ، وأنه باستحقاق أوتي ما أوتي ويقول ( رَبِّي أَكْرَمَنِ ) حذفت الياء تخفيفا ، أي أن هذا لكرامتي على الله ، ولا يعتبره امتحانا."},{"text":"وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَـٰنَنِ","tafsir":""},{"text":"كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ","tafsir":"أي امتحنه الله سبحانه بالفقر والضعة ( فَقَدَرَ ) أي ضيق ( عَلَيْهِ ) أي على الإنسان ( رِزْقَهُ ) فجعله فقيرا مملقا فيحزن لذلك ويظن أن ذلك هوان من الله عليه ، ويقول ( رَبِّي أَهانَنِ ) أي أهانني ، ولا يعتبر ذلك ابتلاء ، وهذا بخلاف الإنسان المؤمن الذي يرى كل شيء يصيبه اختبارا وامتحانا ، فيخاف من النعمة لئلا يعصي الله فيها فلا يشكره ، ولا يحزن من الفقر لأنه يعتبره امتحانا له إن صبر كان رفعا لدرجته."},{"text":"وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","tafsir":"ليس الأمر كما ظن هذا الإنسان ، فإن التنعيم ليس لكرامة ، والإفقار ليس لإهانة بل كل ذلك مختلف ، والمجموع للابتلاء والاختبار ( بَلْ ) إنهم غافلون عن حكمة الإعطاء والمنع ، ذاهلون أن كل ذلك للابتلاء ، ولذا لا يقومون بواجب العطاء ـ ولم يذكر القيام بواجب الفقر من الصبر ، لأن الكلام كان موجها نحو الأغنياء من الناس الذين مثل لهم بمصارع عاد وثمود وفرعون ـ ف ـ ( لا تُكْرِمُونَ الْيَتِيمَ (17) وَلا تَحَاضُّونَ عَلى طَعامِ الْمِسْكِينِ (18) وَتَأْكُلُونَ التُّراثَ أَكْلاً لَمًّا (19) وَتُحِبُّونَ الْمالَ حُبًّا جَمًّا (20) كَلاَّ إِذا دُكَّ تِ الْأَرْضُ دَكًّا دَكًّا (21) الْيَتِيمَ ) الذي مات أبواه ، بإيوائه وإعطائه."},{"text":"وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا","tafsir":"من الحض ـ وهو الحث ـ أي لا يحث بعضكم بعضا ( عَلى طَعامِ الْمِسْكِينِ ) أي الفقير الذي أسكنه فقره عن الحركة في الأمور."},{"text":"وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا","tafsir":"أي الميراث ( أَكْلاً لَمًّا ) شديدا تلمون جميعه في الأكل ، بلا إعطاء حقوق الميت ، وحقوق الله ، وحقوق سائر ذوي الميراث ، فإنهم كانوا يحرمون النساء والصبيان والضعفاء من الورثة ، فلا يعطونهم من حقهم شيئا ، وهذا دليل الشرة نحو المال وإنهم لا يجعلون المال دليلا للابتلاء ، بل دليلا لتكريم الله لهم."},{"text":"كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا","tafsir":"أي حبا كثيرا شديدا ، حتى أنهم لا ينفقونه فيما يجب أو يستحب إنفاقه ، كما هو شأن من لا يؤمن بالله واليوم الآخر ، ولا يجعل المال دليل الابتلاء ليعمل فيه بأمر الله ويخشى مغبته."},{"text":"وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا","tafsir":"ليس الأمر كما زعمتم بأنه لا عواقب وخيمة لأعمالكم هذه ، فإن من يظن تكريم الله له يسهل عليه العمل بالوظائف في أموره وشؤونه ف ( إِذا دُكَّتِ الْأَرْضُ ) أي كسر كل شيء على ظهرها ( دَكًّا دَكًّا ) كسرا كسرا ، من جبال ومرتفعات وأنصبة وأشباهها ، وذلك لأن الأرض تسوى حتى لا يبقى على ظهرها عوج ولا أمت. وَجاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا (22) وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنْسانُ وَأَنَّى لَهُ الذِّكْرى (23) يَقُولُ يا لَيْتَنِي قَدَّمْتُ لِحَياتِي (24) فَيَوْمَئِذٍ لا يُعَذِّبُ عَذابَهُ أَحَدٌ (25)"},{"text":"وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ","tafsir":"أي أمر ربك ، كما يظهر ملوك الدنيا في هيبة وجلال ، فإن الهيبة والجلال التي تظهر يوم القيامة لله سبحانه تكون بمثابة مجيء الله سبحانه ، لكنه حيث كان منزها عن الجسم ولوازمه ، يجيء آثار جلاله ( وَ ) جاء ( الْمَلَكُ ) المربطون بذلك اليوم في حال كونهم ( صَفًّا صَفًّا ) أي مصطفين صفوفا متعددة."},{"text":"يَقُولُ يَـٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى","tafsir":"أي يوم القيامة ( بِجَهَنَّمَ ) بأن تمتد نيرانها إلى المحشر بعد ما كانت مبتعدة مستعدة لالتهام الكفار والعاصين ( يَوْمَئِذٍ ) أي في هذا اليوم ـ وأصله يوم إذ كان كذا ـ ( يَتَذَكَّرُ الْإِنْسانُ ) أي يتعظ ويخاف ويهتدي ( وَ ) لكن ( أَنَّى لَهُ الذِّكْرى ) ؟ أي من أين ينفعه التذكر في ذلك اليوم ، فقد مضى وقت نفع التذكر ، وإنما هناك جزاء فقط لا عمل."},{"text":"فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ","tafsir":"الإنسان العاصي ، ( يا لَيْتَنِي قَدَّمْتُ ) عملا صالحا ( لِحَياتِي ) هذه التي تبقى إلى الأبد ، ولكن لا ينفعه التمني ، كما يقول المثل « ندم زيد ولما ينفعه الندم » ."},{"text":"وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ","tafsir":"أي في ذلك اليوم ( لا يُعَذِّبُ عَذابَهُ أَحَدٌ ) أي لا يعذب مثل عذاب الله أحد ، فإن عذابه ليس كسائر أنواع عذاب الناس بعضهم لبعض ، وإنما هو عذاب غريب عجيب. وَلا يُوثِقُ وَثاقَهُ أَحَدٌ (26) يا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ (27) ارْجِعِي إِلى رَبِّكِ راضِيَةً مَرْضِيَّةً (28) فَادْخُلِي فِي عِبادِ ي (29) وَادْخُلِي جَنَّتِي (30)"},{"text":"يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ","tafsir":"يومئذ ( لا يُوثِقُ وَثاقَهُ ) أي مثل وثاقه سبحانه وتعالى ( أَحَدٌ ) والوثاق هو الشد ، يقال أوثقته أي شددته. [28] ثم يخاطب المؤمنون بقوله سبحانه ( يا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ) من أهوال ذلك اليوم ، لما عملت في الدنيا من الإيمان والإطاعة."},{"text":"ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً","tafsir":""},{"text":"فَٱدْخُلِى فِى عِبَـٰدِى","tafsir":"أي إلى ثوابه وجزائه في حال كونك ( راضِيَةً ) عن الله سبحانه ( مَرْضِيَّةً ) له تعالى ، فإنه سبحانه راض عنك بسبب إيمانك وأعمالك."},{"text":"وَٱدْخُلِى جَنَّتِى","tafsir":"زمرة ( عِبادِي ) الصالحين."}]},"90":{"name":"البلد","verses":[{"text":"لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ","tafsir":""},{"text":"وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ","tafsir":"والمراد به مكة ، و « لا » إما للنفي جيء بها للتلويح إلى القسم مع تعظيم المقسم به ، وإما زائدة ، فالمعنى أقسم بهذا البلد ، والآية الثانية تناسب الأمرين باعتبارين."},{"text":"وَوَالِدٍ وَمَا وَلَدَ","tafsir":"يا رسول الله ( حِلٌ ) أي مقيم قد حللت ( بِهذَا الْبَلَدِ ) فإنه قد تشرف بك ، فإن شرف المنزل بشرف النازل ، و « الحل » بمعنى الحال ، وكلاهما بمعنى الساكن ، فهذا البلد إنما يقسم به لشرفه بك أو يعظم فلا يقسم به لشرفه بك."},{"text":"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ","tafsir":"قسما ب ( والِدٍ وَما وَلَدَ ) أي كل والد وكل ولد ، أو المراد آدم عليه‌السلام وأولاده ، فإن كل خلق الله عظيم يصح أن يجعل في معرض القسم. نعم ليس لنا أن نحلف بكل شيء ، لما ورد من قوله صلى‌الله‌عليه‌وآله‌وسلم : « من كان حالفا فليحلف بالله أو ليسكت » (1) . [5] وجواب القسم قوله : ( لَقَدْ خَلَقْنَا الْإِنْسانَ فِي كَبَدٍ ) أي في تعب ومشقة ، فإنه يكابد الشدائد والمصائب والمتاعب ، فإن « الكبد » لغة بمعنى شدة الأمر ، والمعنى أنه لا يزال يكابد الأتعاب ـ بما قدر الله له وللكون من الأنظمة ـ ولذا قال تعالى في حديث قدسي « إني ما جعلت الراحة في الدنيا والناس يطلبونها فيها فلا يجدوها » . [6] إن الإنسان الذي خلق في عناء ومشقة ، ليدل ذلك على ضعفه وعجزه إذا رأى بعض القوة في ذاته عتا وتكبر وزعم أنه لا قادر عليه ( 1) متشابه القرآن ومختلفه : ج 2 ص 198. أَ يَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ (5) يَقُولُ أَهْلَكْتُ مالاً لُبَداً (6) أَ يَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ (7) أَ لَمْ نَجْعَلْ لَهُ عَيْنَيْنِ (8) وَلِساناً وَشَفَتَيْنِ (9) ( أَ يَحْسَبُ ) أي هل يظن ويزعم الإنسان ( أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ ) بسلبه القوة والثروة والحياة وما أشبه ؟ [7] وإذا قيل له : ابتغ مرضاة الله ببذل الأموال في سبيله لأنك عبد عاجز ضعيف له سبحانه ، وهو قادر على تقليبك كيف يشاء ( يَقُولُ ) في الجواب : ( أَهْلَكْتُ ) في الإنفاق ( مالاً لُبَداً ) أي كثيرا ، مأخوذ من تلبد الشيء إذا تراكم بعضه على بعضه ، وحسبي ما أنفقت ـ كما أن هذا هو منطق الأثرياء غالبا ـ ."},{"text":"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ","tafsir":""},{"text":"يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا","tafsir":""},{"text":"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ","tafsir":""},{"text":"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","tafsir":"أي يزعم ( أَنْ لَمْ يَرَهُ أَحَدٌ ) حيث أنفق ؟ بل إنّ الله رآه وعرف قدر إنفاقه ولم يكن ما أنفق كثيرا بالنسبة إلى أمواله وبالنسبة إلى مقابلته بالثواب المرجو في الآخرة للمنفقين. قيل : إنها نزلت في الحرث ، وذلك أنه أذنب ذنبا فاستفتى رسول الله ؟ فأمره أن يكفر ، فقال : لقد ذهب مالي في الكفارات والنفقات منذ دخلت في دين محمد صلى‌الله‌عليه‌وآله‌وسلم . [9] إنه يبخل عن بذل بعض ماله في سبيل الله الذي أودع فيه القوى التي لا تثمن بثمن فلم يؤدّ شكرها ، ولم يبصر بسببها طريق الرشاد ( أَ لَمْ نَجْعَلْ لَهُ عَيْنَيْنِ ) ليبصر بهما ويرى طريقه ؟"},{"text":"وَلِسَانًا وَشَفَتَيْنِ","tafsir":""},{"text":"وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ","tafsir":"؟ لينطق به ويتجمل بالشفة لعدم قبح منظره بفغر الفم. وَهَدَيْناهُ النَّجْدَيْنِ (10) فَلا اقْتَحَمَ الْعَقَبَةَ (11) وَما أَدْراكَ مَا الْعَقَبَةُ (12) فَكُّ رَقَبَةٍ (13) أَوْ إِطْعامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ (14) يَتِيماً ذا مَقْرَبَةٍ (15)"},{"text":"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ","tafsir":"أي أرشدناه ( النَّجْدَيْنِ ) ؟ أي سبيل الخير وسبيل الشر ، وأصل « النجد » هو العلو ، وكأن الطريق موجب لارتفاع الإنسان ارتفاعا معنويا بوصوله إلى حاجته ، أو لظهور الطريق سمي نجدا تشبيها بالمرتفع من الأرض."},{"text":"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ","tafsir":"« الاقتحام » هو الدخول في الشيء بشدة ، و « عقبة » هي الطريق الصعب في الجبل ، أي أن الإنسان لم يشكر تلك النعم التي أعطيناها إياه باقتحام الأمور الحسنة والعمل بها ، وسميت عقبة لشدة أمرها على الإنسان."},{"text":"فَكُّ رَقَبَةٍ","tafsir":"أيها السامع ( مَا الْعَقَبَةُ ) أي ما هي العقبة ؟ وهذا التعبير لتعظيم أمرها والإجلال لها ، ثم فسرت العقبة بأنه عتق العبد والإطعام. [14] العقبة هي ( فَكُّ رَقَبَةٍ ) أي تحرير العبد من إسار الرق ، وإنما أطلق على الإنسان « الرقبة » بعلاقة الجزء والكل ـ كما قرر في البلاغة."},{"text":"أَوْ إِطْعَـٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ","tafsir":""},{"text":"يَتِيمًا ذَا مَقْرَبَةٍ","tafsir":"« أو » بمعنى الواو ، يعني أن من أفراد « العقبة » إطعام الناس ( فِي يَوْمٍ ذِي مَسْغَبَةٍ ) « السغب » هو الجوع ، والمسغبة المجاعة."},{"text":"أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ","tafsir":"مفعول « إطعام » أي ليطعم الطفل الذي مات أبوه ( ذا مَقْرَبَةٍ ) أي ذا قرابة من المطعم ، فإن الإحسان إلى الأقرباء أفضل من الإحسان أَوْ مِسْكِيناً ذا مَتْرَبَةٍ (16) ثُمَّ كانَ مِنَ الَّذِينَ آمَنُوا وَتَواصَوْا بِالصَّبْرِ وَتَواصَوْا بِالْمَرْحَمَةِ (17) أُولئِ كَ أَصْحابُ الْمَيْمَنَةِ (18) إلى غيرهم ، كما قال عليه‌السلام : « لا صدقة وذو رحم كاشح » ـ (1) ."},{"text":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","tafsir":"وهو الفقير الذي أسكنه الفقر ، فإن الأغنياء يتحركون في مختلف حوائجهم ، أما الفقراء فإنهم حيث لا مال لهم لا يتمكنون من التصرف في الشؤون ( ذا مَتْرَبَةٍ ) بمعنى الحاجة الشديدة من قولهم « ترب الرجل » إذا افتقر ، وأصله من التراب ، لأن الفقر يلازم التراب ، لعدم فراش له ليقيه منه ، فالمعنى قد لصق بالتراب من شدة فقره."},{"text":"أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ","tafsir":"لترتيب الكلمة لا ترتيب المطلب ( كانَ ) ذلك الإنسان الذي لم يقتحم العقبة ( مِنَ الَّذِينَ آمَنُوا ) بالله ورسوله وما جاء به ، وهذا عطف على النفي ، أي لم يقتحم العقبة مع كونه مؤمنا ( وَتَواصَوْا بِالصَّبْرِ ) أي أوصى بعضهم بعضا بأن يصبر على الشدائد ، طاعة كانت أو معصية أو مصيبة ، بأن يعمل الأول ، ويترك الثاني ، ولا يجزع في الثالث ( وَتَواصَوْا بِالْمَرْحَمَةِ ) أي برحم الناس والعطف عليهم ، فإن « مرحمة » مصدر ميمي بمعنى الرحم."},{"text":"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ","tafsir":"المتصفون بفك الرقاب وإطعام الطعام والتواصي بالصبر والمرحمة ( أَصْحابُ الْمَيْمَنَةِ ) يؤخذ بهم ـ في القيامة ـ ناحية اليمين نحو الجنان ، ويعطون كتابهم بأيمانهم ، أو أنهم أصحاب يمن وبركة. ( 1) راجع من لا يحضره الفقيه : ج 2 ص 68 ، وردت كلمة محتاج بدل كاشح في الحديث. وَالَّذِينَ كَفَرُوا بِآياتِنا هُمْ أَصْحابُ الْمَشْأَمَةِ (19) عَلَيْهِمْ نارٌ مُؤْصَدَةٌ (20)"},{"text":"عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ","tafsir":"حججنا الدالة على التوحيد وسائر الأصول ( هُمْ أَصْحابُ الْمَشْأَمَةِ ) فإنهم كانوا أصحاب شؤم على أنفسهم."}]},"91":{"name":"الشمس","verses":[{"text":"وَٱلشَّمْسِ وَضُحَىٰهَا","tafsir":""},{"text":"وَٱلْقَمَرِ إِذَا تَلَىٰهَا","tafsir":"أي قسما بالشمس ( وَ ) قسما ب ( ضُحاها ) أي انبساط ضوءها في الآفاق."},{"text":"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","tafsir":"قسما ب ( الْقَمَرِ إِذا تَلاها ) أي تبع الشمس ، فأخذ من ضوئها وسار في عقبها."},{"text":"وَٱلَّيْلِ إِذَا يَغْشَىٰهَا","tafsir":"قسما ب ( النَّهارِ إِذا جَلَّاها ) أي جلى الشمس وأظهرها وفيه لطف حيث أسند تجلية الشمس إلى النهار من باب « القلب » ، فكأن النهار لشدة ضوئه يوضح الشمس ويظهرها ، كما قال أهل البلاغة في قوله « كما طينت بالفدن السياعا » ."},{"text":"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","tafsir":"قسما ب ( اللَّيْلِ إِذا يَغْشاها ) أي يغشي الشمس فيغطيها عن الأبصار ويخفيها."},{"text":"وَٱلْأَرْضِ وَمَا طَحَىٰهَا","tafsir":"قسما ب ( السَّماءِ وَما بَناها ) أي « وقسما بمن بنى السماء » والمراد به الله تعالى ، أو « ما » مصدرية ، أي وبنائها المحكم المتقن."},{"text":"وَنَفْسٍ وَمَا سَوَّىٰهَا","tafsir":"قسما ب ( الْأَرْضِ وَما طَحاها ) « الطحو » بمعنى البسط ، أي ومن بسطها وهو الله ، أو طحوها ، على أن تكون « ما » مصدرية ـ كما سبق ـ ."},{"text":"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا","tafsir":"أي قسما بكل نفس ، والإتيان بها نكرة للتفنن والبلاغة ( وَما سَوَّاها ) أي الذي صنعها ، وكون « ما » موصولة ـ هنا ـ أقرب ، بقرينة الآية التالية. فَأَلْهَمَها فُجُورَها وَتَقْواها (8) قَدْ أَفْلَحَ مَنْ زَكَّاها (9) وَقَدْ خابَ مَنْ دَسَّاها (10) كَذَّبَتْ ثَمُودُ بِطَغْواها (1 1) إِذِ انْبَعَثَ أَشْقاها (12)"},{"text":"قَدْ أَفْلَحَ مَن زَكَّىٰهَا","tafsir":"أي عرّفها بطريق الإلقاء في القلب ( فُجُورَها ) أي عصيانها ( وَتَقْواها ) أي إطاعتها ، فإن كل إنسان يميز بين الخير والشر والطاعة والعصيان ، وهذه الأقسام في هذه السورة وغيرها إنما تلفت الأنظار إلى هذه الآيات والمعارف ، بالإضافة إلى كونها حلفا ، فلا يقال : أية حاجة لهذه الأيمان ؟"},{"text":"وَقَدْ خَابَ مَن دَسَّىٰهَا","tafsir":"هذا هو المقسم له ، أي فاز من زكى نفسه وطهرها من الآثام والكفر."},{"text":"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","tafsir":"أي خسر ( مَنْ دَسَّاها ) أي أخملها وأخفى محلها بالكفر والعصيان ، فإن « دس » نقيض « زكى » . [12] ثم جاء السياق ليهدد الذين يدسون أنفسهم بأن مصيرهم مصير أولئك الأقوام المكذبين من قبلهم ( كَذَّبَتْ ثَمُودُ ) أي قبيلة ثمود وهم قوم صالح عليه‌السلام ( بِطَغْواها ) أي بسبب طغيانها ، فإن الطغيان يوجب التكذيب والكفر كما قال سبحانه ( ثُمَّ كانَ عاقِبَةَ الَّذِينَ أَساؤُا السُّواى أَنْ كَذَّبُوا بِآياتِ اللهِ ) (1) . و « طغوى » و « طغيان » بمعنى واحد ، وهو مجاوزة الحد في العصيان."},{"text":"إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا","tafsir":""},{"text":"فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا","tafsir":"فقد بعثه الأشقياء لارتكاب هذه الجناية ، فانبعث ( أَشْقاها ) أي أشقى ثمود ، بمعنى الفرد الذي هو أكثر شقوة من غيره ( 1) الروم : 11. فَقالَ لَهُمْ رَسُولُ اللهِ ناقَةَ اللهِ وَسُقْياها (13) فَكَذَّبُوهُ فَعَقَرُوها فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاها (14) وَلا يَخافُ عُقْباها (15) من أفراد القبيلة ، وهو « قدار » ، وهو الذي عقر الناقة."},{"text":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا","tafsir":"تفريع على « كذبت » لا على « انبعث » ، والضمير عائد إلى قبيلة ثمود ( رَسُولُ اللهِ ) والمراد به صالح عليه‌السلام : احذروا ( ناقَةَ اللهِ ) بأن تمسوها بسوء ( وَ ) احذروا ( سُقْياها ) أي شربها من الماء فلا تزجروها في شربها ، فقد كان هناك نهر ، وقرر صالح أن يكون ماء النهر يوما للناقة وتعطي بعوضه اللبن بقدر احتياج القبيلة ، ويوما للناس ، وقال لهم : إن مسستم الناقة بسوء أخذكم العذاب ـ كما تقدم تفصيل القصة ـ ."},{"text":"وَلَا يَخَافُ عُقْبَـٰهَا","tafsir":"أي كذب أهل قبيلة ثمود صالحا عليه‌السلام ـ المتقدم باسم « رسول الله » ـ ( فَعَقَرُوها ) أي نحروا الناقة وضربوا يديها ورجليها بالسيف ، والعاقر كان واحدا لكن تآمرهم على ذلك ورضاهم به أوجب إسناد الفعل إلى جميعهم ( فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ ) أي دمر عليهم الله تعالى ، فإن الدمدمة ترديد الحال المستكره بمضاعفة ما فيه المشقة ( بِذَنْبِهِمْ ) أي بسبب ذنبهم بعقر الناقة ( فَسَوَّاها ) أي سوى الله الدمدمة عليهم أجمعين بحيث لم يفلت منها أحد ، أو سوّى الله أرضهم بحيث استوت فلا شيء فيها."}]},"92":{"name":"الليل","verses":[{"text":"وَٱلَّيْلِ إِذَا يَغْشَىٰ","tafsir":""},{"text":"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","tafsir":"أي قسما بالليل ( إِذا يَغْشى ) أي يحيط بظلمته على الأشياء ، وتخصيص بعض الأقسام بأمور خاصة ، من باب التفنن في البلاغة."},{"text":"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ","tafsir":"قسما ب ( النَّهارِ إِذا تَجَلَّى ) أي ظهر وبان وأضاء."},{"text":"إِنَّ سَعْيَكُمْ لَشَتَّىٰ","tafsir":"قسما ب ( ما خَلَقَ الذَّكَرَ وَالْأُنْثى ) « ما » إما موصولة ، أي الذي خلق ، والمراد به الله سبحانه ، وإنما جيء ب « ما » دون « من » لأن « من » في الغالب يستعمل للبشر ونحوهم ، وإما مصدرية أي قسما يخلق الصنفين."},{"text":"فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ","tafsir":"أيها الناس ، في الأمور ، وتطلبكم للأشياء ( لَشَتَّى ) جمع شتيت كمرضى جمع مريض ، أي أنه مختلف ، فمن طالب دنيا ومن طالب آخرة ، والحلف على ذلك باعتبار ما يعقبه من النتائج ، أو لتبديد أوهام الزاعمين بأن السعي ليس إلا للدنيا فحسب ، إذ ليس هناك آخرة."},{"text":"وَصَدَّقَ بِٱلْحُسْنَىٰ","tafsir":"المال في سبيل الله ( وَاتَّقى ) الكفر والمعاصي."},{"text":"فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ","tafsir":"أي بالكلمة الحسنى ، وهي الشهادتان ، وحيث إن المقام كان في الإعطاء تقدم ، ثم ذكر التقوى لأنه من أقسام الإعطاء ، ثم جاء دور العقيدة بعد ذين الأمرين."},{"text":"وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ","tafsir":"أي سنهوّن عليه الطريقة اليسرى ، وهي طريقة الطاعة ، أو نيسره للحياة اليسرى ، أي الأسهل ، فإن من تبع نهج وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنى (8) وَكَذَّبَ بِالْحُسْنى (9) فَسَنُيَسِّرُهُ لِلْعُسْرى (10) وَما يُغْنِي ع َنْهُ مالُهُ إِذا تَرَدَّى (11) الإسلام سهلت عليه الأمور لما في الإسلام من المناهج السهلة الموجبة للسعادة والرفاه يقال « يسره » إذا سهل عليه ، و « يسرى » مؤنث « أيسر » بمعنى الأسهل."},{"text":"وَكَذَّبَ بِٱلْحُسْنَىٰ","tafsir":"بماله فلم ينفقه في سبيل الله ( وَاسْتَغْنى ) أي طلب الغنى بجمع المال والبخل من إنفاقه."},{"text":"فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ","tafsir":"أي بالكلمة الحسنة ، وهي كلمة الشهادتين أو المراد في الموضعين « العدة الحسنى » وهي الثواب والجنة."},{"text":"وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","tafsir":"أي سنهون عليه الطريقة الأعسر وهي طريقة الكفر ، وهذا على سبيل المزاوجة في الكلام ـ من قبيل ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ ) (1) ، إذ الله سبحانه لا يسهل على أحد سبيل العسر ، وإنما المراد أنه سبحانه يخلي بينه وبين ما يعمل ـ ."},{"text":"إِنَّ عَلَيْنَا لَلْهُدَىٰ","tafsir":"أي لا يفيده ماله الذي بخل به ( إِذا تَرَدَّى ) أي هلك وسقط في الهاوية. روي أن رجلا كانت له نخلة فرعها في دار رجل فقير ذي عيال وكان الرجل إذا جاء فدخل الدار وصعد النخلة ليأخذ منها التمر فربما سقطت التمرة فيأخذها صبيان الفقير ، فينزل الرجل من النخلة حتى يأخذ التمر من أيديهم ، فإن وجدها في فم أحدهم أدخل إصبعه حتى يأخذ التمرة من فيه ، فشكا ذلك الرجل إلى النبي صلى‌الله‌عليه‌وآله‌وسلم وأخبره بما يلقى من صاحب النخلة ، فقال النبي صلى‌الله‌عليه‌وآله‌وسلم : اذهب ، ولقي رسول الله ( 1) البقرة : 195. إِنَّ عَلَيْنا لَلْهُدى (12) وَإِنَّ ل َنا لَلْآخِرَةَ وَالْأُولى (13) صاحب النخلة فقال : تعطيني نخلتك المائلة التي فرعها في دار فلان ولك بها نخلة في الجنة ؟ فقال له الرجل : إن لي نخلا كثيرا وما فيه نخلة أعجب إليّ تمرة منها. قال : ثم ذهب الرجل ، فقال رجل كان يسمع الكلام من رسول الله ـ وقيل اسمه أبو دحداح ـ : يا رسول الله أ تعطيني ما أعطيت الرجل نخلة في الجنة إن أنا أخذتها ؟ قال : نعم. فذهب الرجل ولقي صاحب النخلة فساومها منه ، فقال له : أشعرت أن محمدا صلى‌الله‌عليه‌وآله‌وسلم أعطاني بها نخلة في الجنة فقلت له يعجبني تمرها وإن لي نخلا كثيرا فما فيه نخلة أعجب إلى تمرة منها. فقال له الآخر أ تريد بيعها ؟ فقال : لا إلا أن أعطى ما لا أظنه أعطى ؟ قال : فما هناك ؟ قال : أربعون نخلة ، فقال الرجل : جئت بعظيم تطلب بنخلتك المائلة أربعين نخلة ، ثم سكت عنه ، فقال له : أنا أعطيك أربعين نخلة ، فقال له : اشهد إن كنت صادقا ، فمر إلى أناس ، فدعاهم فأشهد له بأربعين نخلة ، ثم ذهب إلى النبي صلى‌الله‌عليه‌وآله‌وسلم فقال : يا رسول الله إن النخلة قد صارت في ملكي ، فهي لك. فذهب رسول الله إلى صاحب الدار ، فقال له : النخلة لك ولعيالك ، فأنزل الله تعالى « والليل » فمن أعطى « أبو دحداح » ومن بخل « صاحب النخلة » (1) ."},{"text":"وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ","tafsir":"أي أن اللازم على الله سبحانه ـ بقاعدة اللطف ـ أن ينصب الأدلة ويرسل الرسل ، أما الاتباع والاهتداء فعلى الناس من شاء اهتدى ومن شاء بقي على ضلاله."},{"text":"فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ","tafsir":"أي الدنيا ، فمن اهتدى منحناه السعادة في ( 1) بحار الأنوار : ج 22 ص 60. فَأَنْذَرْتُكُمْ ناراً تَلَظَّى (14) لا يَصْلاها إِلاَّ الْأَشْقَى (15) الَّذِي كَذَّبَ وَتَوَلَّى (16) وَسَيُجَنَّبُهَا الْأَتْقَى (17) الَّذِي يُؤْتِي مالَهُ يَتَزَكَّى (18) وَما لِأَحَدٍ عِن ْدَهُ مِنْ نِعْمَةٍ تُجْزى (19) الدارين ، ومن بقي على كفره حرم من خير الدنيا وسعادة الآخرة."},{"text":"لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى","tafsir":"أيها الناس ( ناراً تَلَظَّى ) أي تتلظى ـ حذفت إحدى تائيه لقاعدة اجتماع التائين على رأس المضارع ـ ومعنى التلظي المتلهب والمتوقد وهذه النار عذابها أشد."},{"text":"ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","tafsir":"أي لا يدخلها ملازما لها ( إِلَّا الْأَشْقَى ) أي الأكثر شقوة ، وهو الكافر ، مقابل العاصي الذي هو أقل شقوة فإنه وإن دخل النار لكنه لا يلازمها."},{"text":"وَسَيُجَنَّبُهَا ٱلْأَتْقَى","tafsir":"بآيات الله تعالى ، وكفر به ( وَتَوَلَّى ) أي أعرض عن الحق."},{"text":"ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ","tafsir":"أي سيجنب النار ، ويجعل منها على جانب ، ودخول « السين » لكون القيامة في المستقبل ( الْأَتْقَى ) أي الأكثر تقوى وهو المؤمن المطيع ، وأما المؤمن غير المطيع فإنه يدخل فيها وإن خرج بعد مدة."},{"text":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ","tafsir":"أي ينفق ماله في سبيل الله تعالى ( يَتَزَكَّى ) أي يطلب الزكاة والطهارة بإعطاء ماله ، فإن الإنفاق يطهر القلب من الرذائل."},{"text":"إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ","tafsir":"أي لا يعطي الأتقى ماله لأن لأحد عليه إحسانا ، يريد بهذا الإنفاق جزاء ذلك المحسن ، و « من » لنفي إِلاَّ ابْتِغاءَ وَجْهِ رَبِّهِ الْأَع ْلى (20) وَلَسَوْفَ يَرْضى (21) الجنس .. . والمراد أنه لا يعطي جزاء لإحسان ، وإنما عطاؤه لوجه الله سبحانه."},{"text":"وَلَسَوْفَ يَرْضَىٰ","tafsir":"أي طلب رضى ( وَجْهِ رَبِّهِ الْأَعْلى ) أي رضاه سبحانه ، وإنما أضيف إلى « وجه » لأنه الذي يظهر عليه أثر الرضا في الإنسان ، فهو من باب تشبيه المعقول بالمحسوس ، والاستثناء منقطع ، والتقدير لا يعطي ماله جزاء ، بل إنما يعطي قربة إلى الله سبحانه."}]},"93":{"name":"الضحى","verses":[{"text":"وَٱلضُّحَىٰ","tafsir":""},{"text":"وَٱلَّيْلِ إِذَا سَجَىٰ","tafsir":"أي قسما بالضحى ، وهو وقت ارتفاع الشمس في كبد السماء بحيث يعم نورها ، والواو في مثل هذه المواضع استئنافية لتمليح الكلام وتوحيد السياق."},{"text":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","tafsir":"أي قسما بالليل ( إِذا سَجى ) أي سكن واستقر ظلامه ، فإن « السجو » بمعنى السكون."},{"text":"وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ","tafsir":"يا رسول الله ( رَبُّكَ ) أي ما ترك عنك الوحي توديعا لك ، بأن يكون كالمفارق الذي يودع صديقه ( وَما قَلى ) أي ما قلاك ، بمعنى ما أبغضك ، فإن القلى بمعنى المبغض. روى عن الإمام الباقر عليه‌السلام إن جبرئيل أبطأ على رسول الله صلى‌الله‌عليه‌وآله‌وسلم وأنه كانت أول سورة نزلت ( اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ) ثم أبطأ عليه ، فقالت خديجة : لعل ربك قد تركك فلا يرسل إليك ؟ فأنزل الله تبارك وتعالى ( ما وَدَّعَكَ رَبُّكَ وَما قَلى ) (1) ."},{"text":"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","tafsir":"« اللام » للتأكيد ( خَيْرٌ لَكَ ) يا رسول الله ( مِنَ الْأُولى ) أي الدنيا ، فقد أعد لك الخير هناك ، فكيف يتركك ويقلاك في منتصف الطريق ؟"},{"text":"أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ","tafsir":"يا رسول الله ، في الآخرة ( رَبُّكَ ) بما تشاء ( فَتَرْضى ) من كثرة فضله وإحسانه ، ومن جملة ما يعطى صلى‌الله‌عليه‌وآله‌وسلم الشفاعة ـ كما لا يخفى. [7] ثم أخذ السياق يعدد بعض نعم الله سبحانه عليه سابقا ليؤكد أنه صلى‌الله‌عليه‌وآله‌وسلم ( 1) تفسير القمي : ج 2 ص 428. أَ ل َمْ يَجِدْكَ يَتِيماً فَآوى (6) وَوَجَدَكَ ضَالاًّ فَهَدى (7) وَوَجَدَكَ عائِلاً فَأَغْنى (8) فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ (9) وَأَمَّا السَّائِلَ فَلا تَنْهَرْ (10) وَأَمَّا بِ نِعْمَةِ رَبِّكَ فَحَدِّثْ (11) الآن في وسط الطريق بين نعمة سبقت ونعمة تأتي فكيف يقلاه بعد ذلك ؟ ( أَ لَمْ يَجِدْكَ ) الله ( يَتِيماً ) قد مات أبوك ( فَآوى ) أي آواك ، وأعطاك مأوى ومنزلا وعشيرة تأوي إليهم ، في حين أن اليتيم كان ذليلا مهانا لدى أهل الجاهلية ؟"},{"text":"وَوَجَدَكَ ضَآلًّا فَهَدَىٰ","tafsir":""},{"text":"وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ","tafsir":"يا رسول الله ( ضَالًّا ) قد تفردت في أناس جاهليين كالشيء الثمين الذي يضل في صحراء مقفرة ( فَهَدى ) الناس إليك فأخرجك عن الوحشة والتفرد حيث لا يهتدي الناس ؟"},{"text":"فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ","tafsir":"الله ( عائِلاً ) أي فقيرا لا مال لك ( فَأَغْنى ) أغناك بالمال ، كمال خديجة عليها‌السلام وغيره. [10] وإذ قد ذاق الرسول مرارة اليتم والضلال والفقر ، فليحن على البائسين ويعطف على المنكوبين ( فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ ) أي لا تقهره يا رسول الله ، بأن تزعجه وتظلمه. والرسول وإن كان منزها عن ذلك لكن الأوامر والنواهي شاملة له كشمولها لغيره من سائر المكلفين."},{"text":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ","tafsir":""},{"text":"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","tafsir":"الذي يسأل المال ، وهو الفقير ومن أشبهه ( فَلا تَنْهَرْ ) أي لا تطرده خائبا ، بل أعطه شيئا ، أورده ردا جميلا."}]},"94":{"name":"الشرح","verses":[{"text":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","tafsir":""},{"text":"وَوَضَعْنَا عَنكَ وِزْرَكَ","tafsir":"يا رسول الله ( صَدْرَكَ ) ؟ وشرح الصدر توسعته بالأخلاق الفاضلة ، فكأن صدر من لم يكن حليما أو سخيا أو عالما ـ أو ما أشبه ـ ضيق كالإناء الضيق الذي لا يحتوي إلا على شيء قليل ، والنسبة إلى الصدر لأن القلب الذي هو محل الفضائل في الصدر ، ولعل وجه ذلك أن الإنسان إذا ضاق بأمر حمى قلبه ، فيحتاج إلى هواء أكثر لتبريد القلب ، فتنتفخ الرئة انتفاخا كثيرا مما يضيق الصدر حسا ، ثم أن في الاستفهام حلاوة ليس في الإخبار."},{"text":"ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ","tafsir":"أي حططنا ( عَنْكَ ) يا رسول الله ( وِزْرَكَ ) أي حملك الثقيل ، فإن « الوزر » هو الحمل ، وذلك بشرح صدرك حتى لا يثقل عليك حمل التبليغ ، وهذا ما يحسه كل إنسان مرشد ، فإنه في أول أمره يرى حملا ثقيلا عليه من جراء الإرشاد ، ثم يتسع صدره ـ بفضله سبحانه ـ ويحس كأنه وضع عنه الثقل ، حتى يشعر أحيانا بأنه لا حمل إطلاقا."},{"text":"وَرَفَعْنَا لَكَ ذِكْرَكَ","tafsir":"من ثقله ، و « أنقض » بمعنى أسمع الصوت فإن الإنسان إذا حمل حملا ثقيلا سمع لظهره فرقعة ، وهذا هو الإنقاض ـ وذلك من باب التشبيه للمعقول بالمحسوس ـ ."},{"text":"فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا","tafsir":"يا رسول الله ( ذِكْرَكَ ) حتى يعرفك كل أحد بالصدق والأمانة وما أشبه ذلك ، هذا بالإضافة إلى ما رفعه سبحانه ـ بعد ذلك ـ من ذكره في المآذن وغيرها. فَإِنَّ مَعَ الْعُسْرِ يُسْراً (5) إ ِنَّ مَعَ الْعُسْرِ يُسْراً (6) [6] وإذ تقدم بيان أن النبي صلى‌الله‌عليه‌وآله‌وسلم صار في اليسر بعد ما كان في العسر ، جاء السياق يؤكد هذه الحقيقة في مختلف أدوار الحياة لكل إنسان ( فَإِنَّ مَعَ الْعُسْرِ يُسْراً ) فإذا عسر الأمر على الإنسان واشتد كان لا بد وأن يأتي بعده يسر وسهولة."},{"text":"إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا","tafsir":""},{"text":"فَإِذَا فَرَغْتَ فَٱنصَبْ","tafsir":"هذا للتأكيد ، مع أن فيه تأسيسا ، وهو كون « يسر » الثاني غير « يسر » الأول لأنه منكر ، بخلاف « العسر » في الموضعين فإنه واحد ، لكون اللام ـ سواء كان للعهد أو الجنس ـ توجب الإشارة إلى الحصة المعهودة ، ولذا لو قلت « اشتريت فرسا ثم بعت الفرس » فهم ان المبيع هو المشترى ولو قلت « اشتريت فرسا ثم بعت فرسا » فهم أن المبيع غير المشترى. و قد روي أن النبي صلى‌الله‌عليه‌وآله‌وسلم خرج مسرورا فرحا وهو يضحك ويقول : لن يغلب عسر يسرين فان مع العسر يسرا ، إن مع العسر يسرا (1) . أقول : وقد نظم الشاعر ذلك بقوله : إذا ضاقت بك الدنيا تفكر في ألم نشرح تجد يسرين مع عسر إذا ذكرتها تفرح ( 1) مجمع البيان : ج 1 ص 390. فَإِذا فَرَغْتَ فَانْصَبْ ( 7) وَإِلى رَبِّكَ فَارْغَبْ (8)"},{"text":"وَإِلَىٰ رَبِّكَ فَٱرْغَب","tafsir":"يا رسول الله من أمورك الخاصة ( فَانْصَبْ ) في الدعاء والعبادة ، من « النصب » بمعنى التعب ، أي أتعب نفسك في الاشتغال بالله سبحانه."}]},"95":{"name":"التين","verses":[{"text":"وَٱلتِّينِ وَٱلزَّيْتُونِ","tafsir":""},{"text":"وَطُورِ سِينِينَ","tafsir":"أي قسما بهاتين الفاكهتين ، وإنما جاء الحلف بهما لكثرتهما في الشام وحواليها المباركة ـ التي يراد التلميح إليها لكونها مبعث الأنبياء ومهبط ملائكة السماء ـ ."},{"text":"وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","tafsir":"قسما ب ( طُورِ سِينِينَ ) يعني الجبل الذي كلم الله عليه موسى و « سينين » و « سيناء » لغتان فيه فالقسم برزق الله المادي الفواكه ، وفضله المعنوي الرسالات."},{"text":"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ","tafsir":"قسما ب ( هذَا الْبَلَدِ ) وهو مكة ( الْأَمِينِ ) الذي يأمن فيه الخائف ، فكأنه لا يخون وارده بإهلاك وإيذاء."},{"text":"ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ","tafsir":"هذا جواب القسم ، والتقويم بمعنى تصيير الشيء على ما ينبغي أن يكون عليه من التأليف والتعديل يعني الإنسان مخلوق في أحسن طراز من جهة حواسه وظواهره ، ومن جهة مشاعره وأجهزته ، وهذا يناسب القسم ، لأن الكل إحسان وإفضال ففاكهة ، ووحي ، وإنسان ينتفع بهما في مادياته ومعنوياته."},{"text":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","tafsir":"أي أرجعنا الإنسان ( أَسْفَلَ سافِلِينَ ) أي تركناه ولم نلطف به الألطاف الخفية حتى تردى في أبعد مهوى ، وصار في أسفل من كل إنسان ، والمعنى أن الإنسان له شأنية هذا النحو من التردي إذا أعرض عن الإيمان والهدى واتبع الأهواء والشهوات. إِلاَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ (6) فَما يُكَذِّبُكَ بَعْدُ بِالدِّينِ (7) أَلَيْسَ ال لهُ بِأَحْكَمِ الْحاكِمِينَ (8)"},{"text":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","tafsir":"بالله ورسوله واليوم الآخر ( وَعَمِلُوا ) الأعمال ( الصَّالِحاتِ ) الملازمة لاجتناب السيئات ( فَلَهُمْ أَجْرٌ ) وثواب في الآخرة ( غَيْرُ مَمْنُونٍ ) أي غير مقطوع بل متواصل دائم إلى الأبد ، من « منّ » بمعنى قطع."},{"text":"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ","tafsir":"أيها الإنسان ( بَعْدُ ) أي بعد هذه الحجج والآيات وبيان طرفي الإنسان صعودا وهبوطا ( بِالدِّينِ ) أي بالجزاء ، والمعنى ما الذي يسبب أن تكذب بالجزاء بعد أن عرفت الرفعة والانحطاط في الإنسان ، كما لو بين الأستاذ مضرة الرسوب ومنفعة النجاح يتساءل ما الذي يوجب للتلميذ أن يترك درسه ؟"}]},"96":{"name":"العلق","verses":[{"text":"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ","tafsir":""},{"text":"خَلَقَ ٱلْإِنسَـٰنَ مِنْ عَلَقٍ","tafsir":"يا رسول الله ، القرآن مصاحبا قراءتك ( بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ) فإذا قرأ كل إنسان ما يقرأ بدون اسم الله ، فأنت اقرأ مع اسم الله ، و في الحديث أن جبرئيل نزل على الرسول صلى‌الله‌عليه‌وآله‌وسلم في جبل « حراء » بمكة. فقال : « اقرأ » قال صلى‌الله‌عليه‌وآله‌وسلم : أقرأ ولست أنا بقارئ فقال عليه‌السلام : « اقرأ .. . » (1) ."},{"text":"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ","tafsir":"تخصيص بعد التعميم ، فإن « خلق » الأول حيث حذف متعلقة أفاد العموم ( مِنْ عَلَقٍ ) والعلق هو الدم المنجمد الذي ينقلب المني إليه ، بعد استقراره في الرحم ، وهذا هو بدء الإنسان."},{"text":"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ","tafsir":"للتأكيد في القراءة ( وَرَبُّكَ ) يا رسول الله هو ( الْأَكْرَمُ ) من كل كريم ، ومن كرمه خلق الإنسان من تلك العلقة القذرة ، وأوصله إلى المقامات الرفيعة."},{"text":"عَلَّمَ ٱلْإِنسَـٰنَ مَا لَمْ يَعْلَمْ","tafsir":"الإنسان المعارف أو العلوم بسبب القلم فلو لا خلقه للقلم وتعليمه للإنسان الكتابة لبقي الإنسان في دياجير الجهل والرذيلة ، فمنه سبحانه « القراءة » ف « اقرأ .. . » ومنه الكتابة فعلم « بالقلم » ومنه البدء « من علق » ومنه الإيصال إلى الكمال."},{"text":"كَلَّآ إِنَّ ٱلْإِنسَـٰنَ لَيَطْغَىٰٓ","tafsir":"من أنواع العلوم والمعارف. [7] وهل يشكر الإنسان هذا الفضل العظيم لله سبحانه ، حيث أوجده من ( 1) راجع بحار الأنوار : ج 18 ص 174. كَلاَّ إِنَّ الْإِنْسانَ لَيَطْغى (6) أَنْ رَآهُ اسْتَغْنى (7) إِنَّ إِلى رَبِّكَ الرُّجْعى (8) أَ رَأَيْتَ الَّذِي يَنْ هى (9) عَبْداً إِذا صَلَّى (10) العدم إلى أن أبلغه إلى غاية الكمال الجسدي ، وقد كان جاهلا ضالا فأبلغه رتبة العلم والهدى ؟ ( كَلَّا ) لا يشكر الإنسان ، ف ( إِنَّ الْإِنْسانَ لَيَطْغى ) يتجاوز حدوده ويتكبر على ربه. [8] ل ( أَنْ رَآهُ ) أي حين رأى نفسه ( اسْتَغْنى ) في جسمه وماله ويظن أنه غني بعد ذلك فلا يحتاج إلى ربه."},{"text":"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ","tafsir":""},{"text":"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ","tafsir":""},{"text":"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","tafsir":"يا رسول الله ( الرُّجْعى ) مصدر « رجع » ، أي رجوع الخلق ، ويرجع إليه تعالى ـ أي إلى جزائه وحسابه ـ فيمن يرجع هذا الطاغي الذي طغى على الله سبحانه."},{"text":"عَبْدًا إِذَا صَلَّىٰٓ","tafsir":"يا رسول الله ( الَّذِي ) طغى على الله ، حتى أنه ( يَنْهى ) ."},{"text":"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","tafsir":"فإنه لم يكتف بطغيانه على الله في تركه الصّلاة ـ بنفسه ـ حتى أصبح ينهى سائر العباد إذا قاموا للصلاة ؟ أ رأيت هذا الإنسان يا رسول الله ؟ وهذا استفهام لتوبيخ ذلك الشخص الناهي وتهديده. قال القمي : كان الوليد بن المغيرة ينهى الناس عن الصّلاة وأن يطاع الله ورسوله ، فنزلت هذه الآية (1) . و في رواية أخرى أن أبا جهل قال : هل يغير محمد وجهه بين أظهركم ؟ قالوا : نعم. قال : فبالذي يحلف به لئن رأيته يفعل ذلك لأطأن على رقبته ، فقيل : ها هو ذلك يصلي ، فانطلق ليطأ على رقبة الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فما جاءهم إلا وهو ينكص على عقبيه ويتقي بيديه ، فقالوا : ما لك يا أبا الحكم ؟ قال : ( 1) تفسير القمي : ج 2 ص 430. أَ رَأَيْتَ إِنْ كانَ عَلَى الْهُدى (11) أَوْ أَمَرَ بِالتَّقْوى (12) أَ رَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى (13) أَ لَمْ يَعْلَمْ بِأَنَّ اللهَ يَرى (14) كَلاَّ لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعاً بِالنَّاصِيَةِ (15) رأيت بيني وبينه خندقا من نار وهولا وأجنحة ، وقال الرسول صلى‌الله‌عليه‌وآله‌وسلم : و الذي نفسي بيده لو دنى مني لا لاختطفته الملائكة عضوا عضوا (1) ، فأنزل سبحانه « أ رأيت .. . » وكأن التقدير أ رأيت المانع عن الصّلاة ؟ وهل علمت ماذا يكون جزاؤه ؟ لبيان عظمة هذا العمل من حيث الإثم."},{"text":"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","tafsir":"يا رسول الله ( إِنْ كانَ ) العبد الذي صلى ـ وهو الرسول ـ ( عَلَى الْهُدى ) وكانت صلاته حسب أمر الله سبحانه ؟"},{"text":"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","tafsir":"ذلك العبد ( بِالتَّقْوى ) والمخافة من الله سبحانه باجتناب نواهيه ؟ ماذا كان مصير ذلك له ؟ أليس مصيره إلى العذاب والنكال ؟"},{"text":"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ","tafsir":"يا رسول الله ( إِنْ كَذَّبَ ) ذلك الناهي ـ وهو أبو جهل أو الوليد ـ بآيات الله ورسوله ( وَتَوَلَّى ) أي أعرض عن الحق ، ما هي عاقبته ؟"},{"text":"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ","tafsir":"ذلك الناهي ( بِأَنَّ اللهَ يَرى ) عمله ونهيه عن الصّلاة وكذبه وتوليه ؟ ولم يعلم جزاء هذه السيئات ؟ فإنه كيف ينهى ويكفر ويعصي ، وجزاء من يفعل ذلك النار والنكال ؟"},{"text":"نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ","tafsir":"ليس الأمر على ما توهم من أنه لا جزاء على أعماله السيئة ( لَئِنْ لَمْ يَنْتَهِ ) هذا الناهي عن أعماله وسيئاته ( لَنَسْفَعاً بِالنَّاصِيَةِ ) أي لنجرنّه بناصيته إلى النار ، من « سفع » بمعنى جذب الشيء جذبا شديدا ، « والناصية » هي شعر مقدم الرأس ، فإنه أسهل للأخذ وأوجب لانقياد المأخوذ. ( 1) بحار الأنوار : ج 9 ص 170. ناصِيَةٍ كاذِبَةٍ خاطِئَةٍ (16) فَلْيَدْعُ نادِيَهُ (17) سَنَدْعُ الزَّبانِيَةَ (18) كَلاَّ لا تُطِ عْهُ وَاسْجُدْ وَاقْتَرِبْ (19)"},{"text":"فَلْيَدْعُ نَادِيَهُۥ","tafsir":"نسبة الكذب والخطأ إلى الناصية مجاز باعتبار علاقة الجزء والكل ، كما أن نسبة الإيمان إلى الرقبة في قوله ( رَقَبَةٍ مُؤْمِنَةٍ ) (1) كذلك والمراد أن صاحب الناصية كاذب في أقواله خاطئ في أعماله."},{"text":"سَنَدْعُ ٱلزَّبَانِيَةَ","tafsir":"ذلك الإنسان الناهي ( نادِيَهُ ) أي أهل مجلسه وأصدقائه ، فإن « النادي » هو محل الاجتماع ، الذي ينادي بعضهم بعضا إليه ، ونسبة النداء إليه مجاز من باب « اسأل القرية » يعني يدعوهم لخلاصه فهل يتمكنون إنقاذه من بطش الله سبحانه ؟ قال ابن عباس : لما أتى أبو جهل رسول الله صلى‌الله‌عليه‌وآله‌وسلم انتهره الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فقال أبو جهل : أ تنتهرني يا محمد فو الله لقد علمت ما بها أحد أكثر ناديا مني ؟ فأنزل الله هذه الآية."},{"text":"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩","tafsir":"يعني إنا ندعو الملائكة الموكلين بالنار لقبض ذلك الشخص الناهي ، وليدع هو ناديه ، حتى يظهر أينا يغلب الآخر. وهذا تهديد له بأنه لا منقذ له من بطشه سبحانه ، و « الزبانية » جمع « زبينة » وهي النفس التي تدفع ، من « الزين » بمعنى الدفع ، فإن الملائكة يدفعون المجرمين إلى النار دفعا."}]}});
